  template<is_simd_type B> inline B abs_##N(B a) noexcept                                                                                  \
  {                                                                                                                                        \
    return __wasm_math_map<i##N>(a, [](i##N x) { return x < 0 ? i##N(u##N(0) - u##N(x)) : x; });                                           \
